/// Resolved per-slot Effect event state, returned by
/// `ss_runtime_get_active_effect_event`.
///
/// The runtime forward-scans the parent's `EventsPerFrame` and reports the
/// most recent `EventEffect` whose `frame_index <= current parent frame`
/// for `slot_index`. When no event is active, the runtime falls back to the
/// part's `InitialEvents.effect` (if present); if neither exists, returns
/// SS6 default semantics: `is_synthetic_default = true`, `start_time = 0`,
/// `speed = 1.0`, `independent = false`.
final class ss_effect_event_info extends ffi.Struct {
  /// Parent `frame_index` this `EventEffect` was emitted at; 0 for synthetic default
  /// or `InitialEvents.effect` fallback.
  @ffi.Int32()
  external int event_frame;

  @ffi.Int32()
  external int start_time;

  @ffi.Float()
  external double speed;

  @ffi.Bool()
  external bool independent;

  /// `true` = no real `EventEffect` matched (either `InitialEvents.effect` fallback
  /// or full SS6 default), `false` = real `EventEffect` matched.
  @ffi.Bool()
  external bool is_synthetic_default;

  static ffi.Pointer<ss_effect_event_info> $allocate(
    ffi.Allocator $allocator, {
    required int event_frame,
    required int start_time,
    required double speed,
    required bool independent,
    required bool is_synthetic_default,
  }) => $allocator<ss_effect_event_info>()
    ..ref.event_frame = event_frame
    ..ref.start_time = start_time
    ..ref.speed = speed
    ..ref.independent = independent
    ..ref.is_synthetic_default = is_synthetic_default;
}

/// Result of `EffectSlot::step` / `ss_effect_slot_step`.
///
/// `draw_plan_buf` is a FlatBuffer-encoded `EffectDrawPlan` (see
/// `runtime/effect_draw_plan.fbs`). It is valid only when `visible == true`,
/// and only until the next `step` call on the same slot — callers must consume
/// it within the same frame and not retain pointers across calls.
final class ss_effect_step_result extends ffi.Struct {
  @ffi.Bool()
  external bool visible;

  external ffi.Pointer<ffi.Uint8> draw_plan_buf;

  @ffi.UintPtr()
  external int draw_plan_len;

  static ffi.Pointer<ss_effect_step_result> $allocate(
    ffi.Allocator $allocator, {
    required bool visible,
    required ffi.Pointer<ffi.Uint8> draw_plan_buf,
    required int draw_plan_len,
  }) => $allocator<ss_effect_step_result>()
    ..ref.visible = visible
    ..ref.draw_plan_buf = draw_plan_buf
    ..ref.draw_plan_len = draw_plan_len;
}

/// Resolved per-slot Instance event state, returned by
/// `ss_runtime_get_active_event_instance`.
///
/// The runtime forward-scans the parent's `EventsPerFrame` and reports the
/// most recent `EventInstance` whose `frame_index <= current parent frame`
/// for `slot_index`. When no event is active, the function returns SS6
/// default semantics: `is_synthetic_default = true`, `loop_num = 1`,
/// `speed = 1.0`, all label hashes 0 (caller falls back), all flags false.
///
/// `start_label_hash` / `end_label_hash` are returned raw. They are
/// already resolved internally by `ss_instance_slot_step` against the
/// child runtime context, which keeps late binding intact across
/// dynamic-swap of the child ssab.
final class ss_event_instance_info extends ffi.Struct {
  /// Parent `frame_index` this `EventInstance` was emitted at; 0 for synthetic default.
  @ffi.Int32()
  external int event_frame;

  /// 0 = unset → caller should fall back to 0.
  @ffi.Uint32()
  external int start_label_hash;

  @ffi.Int32()
  external int start_offset;

  /// 0 = unset → caller should fall back to (child_total_frames - 1).
  @ffi.Uint32()
  external int end_label_hash;

  @ffi.Int32()
  external int end_offset;

  /// -1 = infinite, >=1 = finite count.
  @ffi.Int32()
  external int loop_num;

  @ffi.Float()
  external double speed;

  @ffi.Bool()
  external bool independent;

  @ffi.Bool()
  external bool reverse;

  @ffi.Bool()
  external bool pingpong;

  /// `true` = SS6 default (no real event active), `false` = real `EventInstance`.
  @ffi.Bool()
  external bool is_synthetic_default;

  static ffi.Pointer<ss_event_instance_info> $allocate(
    ffi.Allocator $allocator, {
    required int event_frame,
    required int start_label_hash,
    required int start_offset,
    required int end_label_hash,
    required int end_offset,
    required int loop_num,
    required double speed,
    required bool independent,
    required bool reverse,
    required bool pingpong,
    required bool is_synthetic_default,
  }) => $allocator<ss_event_instance_info>()
    ..ref.event_frame = event_frame
    ..ref.start_label_hash = start_label_hash
    ..ref.start_offset = start_offset
    ..ref.end_label_hash = end_label_hash
    ..ref.end_offset = end_offset
    ..ref.loop_num = loop_num
    ..ref.speed = speed
    ..ref.independent = independent
    ..ref.reverse = reverse
    ..ref.pingpong = pingpong
    ..ref.is_synthetic_default = is_synthetic_default;
}

/// Result of `InstanceSlot::step` / `ss_instance_slot_step`.
///
/// `transitioned == true` indicates a new EventInstance edge — the caller
/// should run any side effects tied to the child's `play()` (event-sink
/// notifications, etc.) on this tick. Frame stepping is already applied
/// inside `step`, so callers only consume `child_frame_no` to redraw.
final class ss_instance_step_result extends ffi.Struct {
  @ffi.Bool()
  external bool visible;

  @ffi.Bool()
  external bool transitioned;

  @ffi.Bool()
  external bool independent;

  @ffi.Float()
  external double child_frame_no;

  @ffi.Bool()
  external bool child_looped;

  static ffi.Pointer<ss_instance_step_result> $allocate(
    ffi.Allocator $allocator, {
    required bool visible,
    required bool transitioned,
    required bool independent,
    required double child_frame_no,
    required bool child_looped,
  }) => $allocator<ss_instance_step_result>()
    ..ref.visible = visible
    ..ref.transitioned = transitioned
    ..ref.independent = independent
    ..ref.child_frame_no = child_frame_no
    ..ref.child_looped = child_looped;
}
